var CERTS = {
      'cert-dubai': { title: 'Prompt Engineering for AI Systems', src: 'data:application/pdf;base64,' },
      'cert-oracle': { title: 'Oracle Cloud Infrastructure 2025 AI Foundations', src: 'data:application/pdf;base64,' },
      'cert-incode': { title: 'Python Programming - IncodeVision', src: 'data:application/pdf;base64,' },
      'cert-forage': { title: 'Data Analytics Job Simulation - Deloitte', src: 'data:application/pdf;base64,' },
      'cert-upgrad': { title: 'Introduction to Data Analysis using Excel', src: 'data:application/pdf;base64,' },
    };



    // ── PREMIUM CURSOR ──
    (function () {
      var dot = document.getElementById('cur-dot');
      var ring = document.getElementById('cur-ring');
      var trail = document.getElementById('cur-trail');
      var mx = 0, my = 0, rx = 0, ry = 0, tx = 0, ty = 0;

      document.addEventListener('mousemove', function (e) {
        mx = e.clientX; my = e.clientY;
        dot.style.left = mx + 'px';
        dot.style.top = my + 'px';
      });

      (function animCursor() {
        // ring follows with slight lag
        rx += (mx - rx) * 0.35; ry += (my - ry) * 0.35;
        ring.style.left = rx + 'px'; ring.style.top = ry + 'px';
        // trail follows slower
        tx += (mx - tx) * 0.2; ty += (my - ty) * 0.2;
        trail.style.left = tx + 'px'; trail.style.top = ty + 'px';
        requestAnimationFrame(animCursor);
      })();

      // Hover on interactive elements
      var hoverEls = document.querySelectorAll('a,button,[onclick],.proj-card,.ct-card,.hcard,.nav-pill,.hbtn-v,.hbtn-t');
      hoverEls.forEach(function (el) {
        el.addEventListener('mouseenter', function () { document.body.classList.add('cur-hover'); });
        el.addEventListener('mouseleave', function () { document.body.classList.remove('cur-hover'); });
      });

      // Text cursor on paragraphs
      document.querySelectorAll('p,h1,h2,h3,.hero-desc,.about-text,.sec-sub').forEach(function (el) {
        el.addEventListener('mouseenter', function () { document.body.classList.add('cur-text'); });
        el.addEventListener('mouseleave', function () { document.body.classList.remove('cur-text'); });
      });

      // Click effect
      document.addEventListener('mousedown', function () { document.body.classList.add('cur-click'); });
      document.addEventListener('mouseup', function () { document.body.classList.remove('cur-click'); });

      // Hide when mouse leaves window
      document.addEventListener('mouseleave', function () {
        dot.style.opacity = '0'; ring.style.opacity = '0'; trail.style.opacity = '0';
      });
      document.addEventListener('mouseenter', function () {
        dot.style.opacity = '1'; ring.style.opacity = '1'; trail.style.opacity = '1';
      });
    })();

    // ── SPLASH DISMISS ──
    (function () {
      var s = document.getElementById('splash');
      if (!s) return;
      setTimeout(function () { s.classList.add('hide'); setTimeout(function () { s.style.display = 'none'; }, 800); }, 2800);
    })();

    // ── SCROLL ANIMATIONS ──
    (function () {
      var obs = new IntersectionObserver(function (entries) {
        entries.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); } });
      }, { threshold: 0.12 });
      document.querySelectorAll('.anim').forEach(function (el) { obs.observe(el); });
    })();

    // ── COUNTER ANIMATION ──
    var counterDone = false;
    var counterObs = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) {
          var el = e.target;
          var target = parseInt(el.textContent);
          if (isNaN(target)) return;
          var start = 0, dur = 1800, startTime = null;
          function step(ts) {
            if (!startTime) startTime = ts;
            var prog = Math.min((ts - startTime) / dur, 1);
            var ease = 1 - Math.pow(1 - prog, 3);
            el.textContent = Math.floor(ease * target) + (el.dataset.suffix || '');
            if (prog < 1) requestAnimationFrame(step);
            else el.textContent = target + (el.dataset.suffix || '');
          }
          requestAnimationFrame(step);
          counterObs.unobserve(el);
        }
      });
    }, { threshold: 0.5 });
    document.querySelectorAll('.stat-n').forEach(function (el) {
      var txt = el.textContent.trim();
      if (txt.endsWith('+')) { el.dataset.suffix = '+'; el.textContent = txt.slice(0, -1); }
      counterObs.observe(el);
    });

    // ── 3D CARD TILT ──
    document.querySelectorAll('.proj-card,.hcard,.abt-card,.ct-card').forEach(function (card) {
      card.addEventListener('mousemove', function (e) {
        var r = card.getBoundingClientRect();
        var x = (e.clientX - r.left) / r.width - 0.5;
        var y = (e.clientY - r.top) / r.height - 0.5;
        card.style.transform = 'perspective(700px) rotateY(' + (x * 14) + 'deg) rotateX(' + (-y * 14) + 'deg) scale(1.02)';
        card.style.boxShadow = '0 20px 48px rgba(0,0,0,.7),' + (x * 18) + 'px ' + (y * 18) + 'px 36px rgba(124,58,237,.12)';
      });
      card.addEventListener('mouseleave', function () {
        card.style.transform = '';
        card.style.boxShadow = '';
      });
    });

    // ── CERT VIEWER ──
    function openCert(id) {
      var c = CERTS[id]; if (!c) return;
      document.getElementById('cv-title').textContent = c.title;
      document.getElementById('cv-frame').src = c.src;
      document.getElementById('cv-overlay').classList.add('open');
      document.body.style.overflow = 'hidden';
    }
    function closeCert() {
      document.getElementById('cv-overlay').classList.remove('open');
      document.getElementById('cv-frame').src = '';
      document.body.style.overflow = '';
    }
    function closeCertOutside(e) { if (e.target === document.getElementById('cv-overlay')) closeCert(); }

    // ── PROJECT MODALS ──
    function openModal(id) { var el = document.getElementById(id); if (el) { el.classList.add('open'); document.body.style.overflow = 'hidden'; } }
    function closeModal(id) { var el = document.getElementById(id); if (el) { el.classList.remove('open'); document.body.style.overflow = ''; } }
    function closeModalOutside(e, id) { if (e.target === document.getElementById(id)) closeModal(id); }

    // ── EXPERIENCE TABS ──
    function swE(idx, btn) {
      document.querySelectorAll('.etab').forEach(function (t) { t.classList.remove('active'); });
      document.querySelectorAll('.exp-panel').forEach(function (p) { p.classList.remove('active'); });
      btn.classList.add('active');
      var panel = document.getElementById('ep-' + idx);
      if (panel) panel.classList.add('active');
    }

    // ── THEME TOGGLE ──
    function toggleTheme() {
      var isLight = document.body.classList.toggle('light-theme');
      var btn = document.getElementById('theme-btn');
      if (btn) btn.textContent = isLight ? '🌑' : '🌙';
      try { localStorage.setItem('theme', isLight ? 'light' : 'dark'); } catch (e) { }
    }
    (function () {
      try {
        if (localStorage.getItem('theme') === 'light') {
          document.body.classList.add('light-theme');
          var btn = document.getElementById('theme-btn');
          if (btn) btn.textContent = '🌑';
        }
      } catch (e) { }
    })();

    // ── MUSIC ──
    var music = document.getElementById('bg-music');
    var mwBars = document.querySelectorAll('.mwb');
    var musicPlaying = false;
    function setMusicUI(playing) {
      mwBars.forEach(function (b) { playing ? b.classList.add('on') : b.classList.remove('on'); });
      var s = document.getElementById('mw-status');
      var i = document.getElementById('mw-icon');
      if (s) s.textContent = playing ? 'NOW PLAYING' : 'PAUSED';
      if (i) i.textContent = playing ? '⏸' : '▶';
      musicPlaying = playing;
    }
    function toggleMusic() {
      if (musicPlaying) { music.pause(); setMusicUI(false); }
      else { music.volume = 0.9; music.play().then(function () { setMusicUI(true); }).catch(function () { }); }
    }
    var autoStarted = false;
    function autoStart() {
      if (autoStarted) return; autoStarted = true;
      music.volume = 0.9;
      music.play().then(function () { setMusicUI(true); }).catch(function () { });
    }
    music.volume = 0.9;
    music.play().then(function () { autoStarted = true; setMusicUI(true); }).catch(function () {
      ['click', 'scroll', 'touchstart', 'keydown'].forEach(function (ev) {
        document.addEventListener(ev, autoStart, { once: true });
      });
    });

    // ── SERVICE WORKER (offline support) ──
    if ('serviceWorker' in navigator) {
      window.addEventListener('load', function () {
        var swCode = [
          "self.addEventListener('install',function(e){",
          "  e.waitUntil(caches.open('av-portfolio-v1').then(function(cache){",
          "    return cache.addAll(['/']);",
          "  }));",
          "});",
          "self.addEventListener('fetch',function(e){",
          "  e.respondWith(caches.match(e.request).then(function(r){",
          "    return r || fetch(e.request).then(function(res){",
          "      var clone = res.clone();",
          "      caches.open('av-portfolio-v1').then(function(c){ c.put(e.request, clone); });",
          "      return res;",
          "    });",
          "  }));",
          "});"
        ].join('\n');
        var blob = new Blob([swCode], { type: 'application/javascript' });
        navigator.serviceWorker.register(URL.createObjectURL(blob)).catch(function(){});
      });
    }
